<script setup lang="ts">
import { PhCalendarCheck,PhArrowRight,PhCrosshair,PhArrowsClockwise } from '@phosphor-icons/vue'
import { maintenancePlans,maintenanceDue,maintenanceStatusLabels,intervalLabel,formatDate,formatMinutes,flightTotals,demoSnapshot,addDays,type MaintenancePlan } from '../data/operations'
import type { RecordDetails,WorkspaceNavigation } from '../types/workspace'
const props=defineProps<{viewerReady:boolean;navigation?:WorkspaceNavigation|null}>()
const emit=defineEmits<{inspect:[detail:RecordDetails];locate:[sourceName:string]}>()
const state=ref('all')
const plans=maintenancePlans.map(plan=>({...plan,due:maintenanceDue(plan)}))
const filtered=computed(()=>plans.filter(plan=>state.value==='all'||(state.value==='attention'?plan.due.status!=='planned':plan.due.status===state.value)))
watch(()=>props.navigation?.id,()=>{if(!props.navigation)state.value='all';else if(props.navigation.tab==='maintenance')state.value=props.navigation.maintenance??'all'},{immediate:true})
function inspect(plan:MaintenancePlan){
 const due=maintenanceDue(plan)
 const dates=plan.everyDays&&due.nextDate?[0,1,2].map(i=>formatDate(addDays(due.nextDate!,i*plan.everyDays!))).join(' → '):'Mengikuti akumulasi utilisasi'
 emit('inspect',{eyebrow:`JADWAL BERULANG / ${plan.id}`,title:plan.title,description:plan.note,fields:[{label:'Interval contoh',value:intervalLabel(plan)},{label:'Terakhir dicatat',value:formatDate(plan.lastDate)},{label:'Kalender berikutnya',value:due.nextDate?formatDate(due.nextDate):'Mengikuti utilisasi'},{label:'Batas jam berikutnya',value:plan.everyMinutes?formatMinutes(plan.lastMinutes+plan.everyMinutes):'Tidak ditetapkan'},{label:'Batas siklus berikutnya',value:plan.everyCycles?`${plan.lastCycles+plan.everyCycles} siklus`:'Tidak ditetapkan'},{label:'Status pada snapshot',value:maintenanceStatusLabels[due.status]},{label:'Tiga tanggal pada pola kalender',value:dates}],note:'Batas yang tercapai lebih dulu menentukan status contoh. Daftar tanggal memperlihatkan pola berulang, bukan catatan pekerjaan yang sudah diselesaikan. Program perawatan resmi belum dimasukkan.'})
}
</script>
<template>
 <section class="operations-page maintenance-page" aria-labelledby="maintenance-title">
  <header class="operations-heading"><div><span class="operations-eyebrow">C208 / MAINTENANCE PLANNING</span><h2 id="maintenance-title">Jadwal maintenance</h2><p>Perulangan berdasarkan kalender, jam terbang, atau siklus yang ditetapkan pada demo.</p></div><span class="data-origin">Interval contoh</span></header>
  <p class="operations-data-note"><PhCalendarCheck :size="19" /> Interval ini hanya untuk simulasi aplikasi dan belum berasal dari program perawatan resmi pesawat.</p>
  <div class="maintenance-snapshot"><span>Posisi data: <strong>{{ formatDate(demoSnapshot) }}</strong></span><span>{{ formatMinutes(flightTotals.minutes) }} terbang <span>·</span> {{ flightTotals.cycles }} siklus contoh</span></div>
  <div class="operations-metrics"><div><span>Jadwal berulang</span><strong>{{ plans.length }}</strong><small>Aturan aktif di demo</small></div><div><span>Jatuh tempo</span><strong>{{ plans.filter(p=>p.due.status==='due').length }}</strong><small>Batas sudah tercapai</small></div><div><span>Segera</span><strong>{{ plans.filter(p=>p.due.status==='soon').length }}</strong><small>Mendekati salah satu batas</small></div><div><span>Terjadwal</span><strong>{{ plans.filter(p=>p.due.status==='planned').length }}</strong><small>Batas masih tersedia</small></div></div>
  <div class="operations-section-heading"><div><h3>Rencana berulang</h3><p>Status mengikuti batas kalender atau utilisasi yang tercapai lebih dulu.</p></div><label class="operations-select"><span>Status jadwal</span><select v-model="state" aria-label="Filter status maintenance"><option value="all">Semua status</option><option value="attention">Jatuh tempo / segera</option><option v-for="(label,key) in maintenanceStatusLabels" :key="key" :value="key">{{ label }}</option></select></label></div>
  <div class="maintenance-plans"><article v-for="plan in filtered" :key="plan.id" class="maintenance-plan" :data-plan-id="plan.id"><div class="maintenance-plan-heading"><span class="maintenance-plan-icon"><PhArrowsClockwise :size="22" /></span><div><span class="record-code">{{ plan.id }} · {{ plan.category }}</span><h4>{{ plan.title }}</h4></div><span class="operation-status" :class="plan.due.status">{{ maintenanceStatusLabels[plan.due.status] }}</span></div><div class="maintenance-rule"><span>Berulang setiap</span><strong>{{ intervalLabel(plan) }}</strong></div><dl class="maintenance-plan-dates"><div><dt>Terakhir dicatat</dt><dd>{{ formatDate(plan.lastDate) }}</dd></div><div v-if="plan.due.nextDate"><dt>Kalender berikutnya</dt><dd>{{ formatDate(plan.due.nextDate) }}<small>{{ plan.due.daysLeft!<=0?`${Math.abs(plan.due.daysLeft!)} hari melewati batas`:`${plan.due.daysLeft} hari lagi` }}</small></dd></div><div v-if="plan.due.minutesLeft!==undefined"><dt>Sisa jam contoh</dt><dd>{{ plan.due.minutesLeft<=0?'Batas telah tercapai':formatMinutes(plan.due.minutesLeft) }}</dd></div><div v-if="plan.due.cyclesLeft!==undefined"><dt>Sisa siklus contoh</dt><dd>{{ Math.max(0,plan.due.cyclesLeft) }} siklus</dd></div></dl><div class="maintenance-plan-actions"><button class="button subtle" @click="inspect(plan)">Detail perulangan<PhArrowRight :size="16" /></button><button class="button subtle" :disabled="!viewerReady" @click="emit('locate',plan.sourceName)"><PhCrosshair :size="17" /> Lokasi 3D</button></div></article></div>
 </section>
</template>
